        originalTitle: "Veni, veni Emmanuel",
        lyrics: `1.
Draw nigh, draw nigh, Emmanuel,
And loose Thy captive Israel,
That mourns in lonely exile here,
Until the Son of God appear!

CHORUS:
Rejoice! Rejoice! Emmanuel
Shall come to thee, O Israel.

2.
Thou, the true East, draw nigh, draw nigh,
To give us comfort from on high!
And drive away the shades of night,
Piercing the clouds, and bringing light!

CHORUS:
Rejoice! Rejoice! Emmanuel
Shall come to thee, O Israel.

3.
Draw nigh, draw nigh, Thou Lord of Might,
Who to Thy flock on Sina's height
Didst give, of ancient times, Thy law,
In cloud, and majesty, and awe.

CHORUS:
Rejoice! Rejoice! Emmanuel
Shall come to thee, O Israel.`
