        language: "English",
        originalTitle: "Peaceful eve, so still and holy",
        lyrics: `1.
Peaceful eve, so still and holy,
When in stable mean and lowly,
Radiant stood the Mother-Maid.
Yearning love her heart is filling;
Wonder deep her soul is thrilling,
While in sleep her Babe is laid.
Pillowed on her virgin breast,
God the Son doth gently rest.

2.
Who can view without emotion
That fond Mother's deep devotion?
All her soul with gladness sings.
For she knows that earthly Mother,
Blest is she beyond all other;
She hath borne the King of kings.
See redemption's work begun!
Mary bears both God and Son.

3.
So would we with holy daring,
Through this Christmas-tide be sharing
In thy joy, O Mother dear.
Christ we claim as our possession:
By thy mighty intercession
Keep us in this love and fear.
And when death's dark gates are passed,
Lead us to His Feet at last.`
