        number: 100,
        title: "Hail, Holy Queen Enthroned Above",
        category: "Feasts of the Blessed Virgin Mary",
        language: "English",
        originalTitle: "Salve Regina, Mater misericordiae",
        lyrics: `
1.
Hail, holy Queen enthroned above,
O Maria!
Hail, Mother of mercy and of love,
O Maria!

CHORUS:
Triumph, all ye Cherubim,
Sing with us, ye Seraphim,
Heaven and earth resound the hymn:
Salve, salve, salve Regina!

2.
Our life, our sweetness here below,
O Maria!
Our hope in sorrow and in woe,
O Maria!

CHORUS:
Triumph, all ye Cherubim,
Sing with us, ye Seraphim,
Heaven and earth resound the hymn:
Salve, salve, salve Regina!

3.
To thee we cry, poor sons of Eve,
O Maria!
To thee we sigh, we mourn, we grieve,
O Maria!

CHORUS:
Triumph, all ye Cherubim,
Sing with us, ye Seraphim,
Heaven and earth resound the hymn:
Salve, salve, salve Regina!

4.
This earth is but a vale of tears,
O Maria!
A place of banishment and of fears,
O Maria!

CHORUS:
Triumph, all ye Cherubim,
Sing with us, ye Seraphim,
Heaven and earth resound the hymn:
Salve, salve, salve Regina!

5.
Turn, then, most gracious Advocate,
O Maria!
Towards us thine eyes compassionate,
O Maria!

CHORUS:
Triumph, all ye Cherubim,
Sing with us, ye Seraphim,
Heaven and earth resound the hymn:
Salve, salve, salve Regina!

6.
When this our exile is complete,
O Maria!
Show us thy Son, our Jesus sweet,
O Maria!

CHORUS:
Triumph, all ye Cherubim,
Sing with us, ye Seraphim,
Heaven and earth resound the hymn:
Salve, salve, salve Regina!

7.
O clement, gracious Mother sweet,
O Maria!
O Virgin Mary, we entreat,
O Maria!

CHORUS:
Triumph, all ye Cherubim,
Sing with us, ye Seraphim,
Heaven and earth resound the hymn:
Salve, salve, salve Regina!
        `
