        number: 108,
        title: "Dear Mary Fair and Tender",
        category: "Feasts of the Blessed Virgin Mary",
        language: "English",
        originalTitle: "Our Lady of Perpetual Succor",
        lyrics: `
1.
Dear Mary fair and tender,
O Mother sweet and mild,
To thee our love we render,
And homage undefiled.
To thee our love is plighted,
Our souls with thee united;
O Mary, O Mary,
Ever lend thy help.

2.
With trust and hope inspiring
All gather round thy throne;
From thee thy grace imploring,
And from thy blessed Son.
Deep faith from thee we borrow,
In every woe and sorrow;
O Mary, O Mary,
Ever lend thy help.

3.
O Virgin pure and holy,
Fulfil the promised word;
And in thy place of glory,
May all our prayers be heard.
Continual succor lending
And blessings to us sending;
O Mary, O Mary,
Ever lend thy help.

4.
And when the hour is nearing
Of sure approaching death,
Oh let us, without fearing,
Exhale our dying breath:
Hast led us through probation,
Through thee we'll gain salvation.
O Mary, O Mary,
Ever lend thy help.
        `
