        title: "O Vision Bright",
        category: "Feasts of the Blessed Virgin Mary",
        language: "English",
        originalTitle: "Regina Angelarum",
        lyrics: `
1.
O vision bright! The land of light
Beams goldenly beyond the sky;
Mid heavenly fires, o'er angel choirs,
Mary, our Mother, reigns on high.

2.
O vision bright! The Father's might
Around His daughter's throne doth lie;
Where, in the balm of endless calm,
Mary, our Mother, reigns on high.

3.
O vision bright! The eternal light
Of the dear Son may we descry;
Where, brighter far than moon or star,
Mary, our Mother, reigns on high.

4.
O vision bright! In softest flight
The Dove around His spouse doth fly;
Where, in that height of matchless light,
Mary, our Mother, reigns on high.

5.
O vision bright! Angels' delight!
The Mother sits with Jesus nigh:
Her form He bears, her look He wears;
Mary, our Mother, reigns on high.
        `
