        title: "Holy One in Godhead Three",
        category: "General Hymns",
        language: "English",
        originalTitle: "Tu Trinitatis unitatis",
        lyrics: `
1.
Holy One in Godhead Three,
Ruler of the earth and sea,
Hear us while we lift to Thee
Holy chant and hymn.

2.
Light of lights, with morning shine,
Lift on us Thy light divine;
And let charity benign
Breathe on us her heaven.

3.
Light of lights, when even falls,
Let close on sin forgiven;
Fold us in the peace of heaven,
Shed a holy balm.

4.
Holy Godhead, One in Three,
Dimly here we worship Thee;
With the Saints hereafter we
Hope to bear the palm.
        `
