        category: "Holy Spirit",
        language: "Latin",
        originalTitle: "Veni Sancte Spiritus",
        lyrics: `
Veni, Sancte Spiritus,
Et emitte caelitus
Lucis tuae radium.

Veni, pater pauperum,
Veni, dator munerum,
Veni, lumen cordium.

Consolator optime,
Dulcis hospes animae,
Dulce refrigerium.

In labore requies,
In aestu temperies,
In fletu solatium.

O lux beatissima,
Reple cordis intima
Tuorum fidelium.

Sine tuo numine,
Nihil est in homine,
Nihil est innoxium.

Lava quod est sordidum,
Riga quod est aridum,
Sana quod est saucium.

Flecte quod est rigidum,
Fove quod est frigidum,
Rege quod est devium.

Da tuis fidelibus,
In te confidentibus,
Sacrum septenarium.

Da virtutis meritum,
Da salutis exitum,
Da perenne gaudium.
        `
