        category: "Blessed Virgin Mary",
        language: "Latin",
        originalTitle: "Ut Jucundas Cervus Undas",
        lyrics: `
Ut jucundas cervus undas
Aestuans desiderat,
Sic ad rivum Dei vivum
Mens fidelis properat.

Sicut rivi fontis vivi
Praebent refrigerium,
Ita menti sitienti
Deus est remedium.

Quantis bonis superponis
Sanctos tuos, Domine;
Sese laedit qui recedit
Ab aeterno lumine.

Vitam laetam et quietam,
Qui te quaerit reperit;
Nam laborem et dolorem
Metit qui te deserit.

Pacem donas et coronas
His qui tibi militant;
Cuncta laeta sine meta
His qui tecum habitant.

Heu quam vana, mens humana,
Visione falleris,
Dum te curis nocituris
Imprudenter inseris.

Recordare quis et quare
Sis a Deo conditus;
Hujus heres nunc maneres,
Si fuisses subditus.

O mortalis, quantis malis
Meruisti affici,
Dum Rectori et Auctori
Noluisti subjici.

Sed majores sunt dolores
Infernalis carceris,
Quo mittendus et torquendus
Es, si male vixeris.

Cui mundus est jucundus,
Suam perdit animam;
Pro re levi atque brevi
Vitam perdit optimam.

Ergo cave ne suave
Jugum spernas Domini,
Nec abjecta lege recta
Servias libidini.

Preces funde, pectus tunde,
Flendo cor humilia;
Paenitenti et gementi
Non negatur venia.
        `
