    {
        number: 40,
        title: "Ecquis Binas Columbinas",
        category: "Passion",
        language: "Latin",
        originalTitle: "Ecquis Binas Columbinas",
        lyrics: `
Ecquis binas columbinas
Alas dabit animae?
Ut in almam crucis palmam
Evolet citissime,
In qua Jesus totus laesus,
Orbis desiderium,
Et immensus est suspensus,
Factus improperium.

O cor, scande Jesu, pande
Caritatis viscera,
Et profunde me reconde
Intra sacra vulnera;
In superna me caverna
Colloca maceriae;
Hic viventi, quiescenti
Finis est miseriae.

O mi Deus, amor meus!
Tune pro me pateris?
Proque indigno, crucis ligno,
Jesu, me suffigeris?
Pro latrone, Jesu bone,
Tu in crucem tolleris?
Pro peccatis meis gratis,
Vita mea, moreris?

Non sum tanti, Jesu, quanti
Amor tuus aestimat;
Heu! cur ego vitam dego,
Si cor te non redamat?
Benedictus sit invictus
Amor vincens omnia;
Amor fortis, tela mortis
Reputans ut somnia.

Iste fecit et refecit,
Amor, Jesu, perditum;
O insignis, Amor, ignis,
Cor accende frigidum;
O fac vere cor ardere,
Fac me te diligere;
Da conjungi, da defungi
Tecum, Jesu, et vivere.
        `
    },

    {
        number: 41,
        title: "Ad Quem Diu Suspiravi",
        category: "Holy Communion",
        language: "Latin",
        originalTitle: "Ad Quem Diu Suspiravi",
        lyrics: `
Ad quem diu suspiravi,
Jesum tandem habeo;
Hunc amplector, quem optavi,
Quem optavi teneo.

Omnes meae exsultate,
Facultates animae;
Exsultate, triumphate,
Et ingresso plaudite.

Tristis eram et abjectus,
Eram sine gaudio,
Quia aberat dilectus,
Quem prae cunctis diligo.

Sed ut venit et intravit
Animae tugurium,
O quam dulce permeavit
Meum cor solatium!

Non sic terras umbris tectas
Gratus sol illuminat,
Non sic aestibus dejectas
Nimbus herbas recreat,
Sicut animam languentem
Refocillat Dominus,
Hanc tristantem et torpentem
Novis donat viribus.

Felix dies, felix hora,
Qua me, Jesu, visitas;
Pulchra nimis et decora
Lux, ad me quae properas.
Qui te tenet habet satis,
Quia, qui te possidet,
Uberem felicitatis
Verae fontem obtinet.

Quis non tuam admiretur
Bonitatem, Domine,
Si quod facis meditetur
Serio examine?
Ad te ruo, ad me ruis,
Et me sinis protinus
Immiscere meos tuis
Amplexus amplexibus.

Nihil eram, me creasti
Ex obscuro nihilo,
Divinaeque me donasti
Rationis radio.
Pro me nasci voluisti
In deserto stabulo,
Et finire morte tristi
Vitam in patibulo.

Praeter dona quibus ditas
Me diebus singulis,
Dapes hodie mellitas
Datis addis gratiis.
O voluptas cordis mei,
Jesu dilectissime!
In me regna, Fili Dei,
Regna, regna libere.

In me proprium amorem
Tam potenter eneces,
Ut te amem et adorem
Solum, sicut dignus es.
In me tolle quod est puris
Grave tuis oculis,
Ut sic artius venturis
Tibi jungar saeculis.

Oriente sole mane,
Occidente vespera,
Bone Jesu, mecum mane,
Mecum semper habita.
Nil abs te, nec mors nec vita,
Nil abs te me separet;
Unio sit infinita,
Quam vis nulla terminet.

Canam, donec respirabo,
Gratiarum cantica;
Millies haec iterabo
In caelesti patria,
Quando te, remoto velo,
Sicut es, aspiciam,
Et cum angelis in caelo
In aeternum diligam.
        `
    }

